# Catálogo nativo de shell para deploy/install.sh. Solo lo carga el instalador.
case "$key" in
  install_detached) fmt='La instalación continúa en segundo plano. Registro: %s\nCódigo de salida al finalizar (0 = éxito): %s\n' ;;
  install_detach_failed) fmt='No se pudo iniciar la instalación en segundo plano; no se cambiaron los servicios.\n' ;;
  install_already_running) fmt='Ya hay una instalación en curso.\n' ;;

  need_root) fmt='Debe ejecutarse como root (prueba: sudo bash deploy/install.sh)\n' ;;
  no_systemd) fmt='No se encontró systemd; este instalador está dirigido a hosts con systemd\n' ;;
  platform_unsupported) fmt='Solo se admite Linux x86-64.\n' ;;
  legacy_state_unsupported) fmt='Existe una instalación antigua o incompleta. Esta versión no migra su estado automáticamente. Restaura una copia o realiza una instalación nueva de forma deliberada; los servicios no se han modificado.\n' ;;
  state_layout_invalid) fmt='La ubicación de datos persistentes no es válida o contiene archivos ajenos; la instalación se detuvo antes de modificar servicios.\n' ;;
  no_python) fmt='No se encontró python3 (apt install python3)\n' ;;
  no_openssl) fmt='No se encontró openssl (apt install openssl), o configura VPSSRV_CONSOLE_TLS=0 para usar HTTP sin cifrar\n' ;;
  installing) fmt='Instalando en %s ...\n' ;;
  inplace_skip) fmt='El origen es el directorio de instalación: se omite la copia de archivos (actualización en el sitio).\n' ;;
  missing_app) fmt='Falta %s/app.py después del paso de copia\n' ;;
  auth_disabled) fmt='Protección por contraseña desactivada: cualquiera que encuentre el puerto podrá entrar sin iniciar sesión.\n' ;;
  anytls_failed) fmt='\nNo se pudo instalar el módulo anytls. El módulo web anterior está instalado y en ejecución; solo falta anytls. Vuelve a ejecutar con VPSSRV_MODULES=anytls cuando resuelvas la causa.\n' ;;
  proxy_failed) fmt='\nNo se pudo instalar el módulo proxy. El módulo web anterior está instalado y en ejecución; solo falta proxy. Vuelve a ejecutar con VPSSRV_MODULES=proxy cuando resuelvas la causa.\n' ;;
  container) fmt='Se detectó un contenedor: se omiten las directivas de aislamiento de systemd (aquí fallan con 226/NAMESPACE).\n' ;;
  writing_unit) fmt='Escribiendo %s ...\n' ;;
  start_failed) fmt='\nNo se pudo iniciar el servicio. Registro reciente:\n' ;;
  running) fmt='\nvps-server está en ejecución.\n' ;;
  line_service) fmt='  servicio:  systemctl status %s\n' ;;
  line_url) fmt='  url:       %s://%s:%s/\n' ;;
  line_url_unknown) fmt='  url:       %s://%s:<port>/   (no se pudo leer %s; comprueba journalctl -u %s)\n' ;;
  line_pw_none) fmt='  contraseña: ninguna; la protección por contraseña está desactivada (VPSSRV_AUTH=0)\n' ;;
  line_pw) fmt='  contraseña: %s   (guardada en %s)\n' ;;
  line_pw_preserved) fmt='  contraseña: se conserva el archivo en %s (no se muestra su contenido)\n' ;;
  line_pw_seefile) fmt='  contraseña: consulta %s\n' ;;
  line_lang) fmt='  idioma: %s (predeterminado si no coinciden cookie, consulta ni navegador)\n' ;;
  cert_note) fmt='\nAviso: se usa un certificado autofirmado, por lo que los navegadores mostrarán una advertencia\nque tendrás que aceptar. Para usar un certificado real, configura VPSSRV_TLS_CERT\ny VPSSRV_TLS_KEY y vuelve a ejecutar este instalador.\n' ;;
  to_remove) fmt='\nDesinstalar y conservar los datos:\n  sudo PREFIX=%s SERVICE_NAME=%s KEEP_DATA=1 bash deploy/uninstall.sh\nDesinstalar y borrar los datos del proyecto:\n  sudo PREFIX=%s SERVICE_NAME=%s bash deploy/uninstall.sh\n' ;;
  port_registration_failed) fmt='No se pudo registrar el puerto de %s en PORTS.md; se detuvo el servicio.\n' ;;
  nft_runtime_failed) fmt='Falta el entorno nftables incluido o no supera la verificación.\n' ;;
  tailscale_install_failed) fmt='Falló la instalación de Tailscale; consulte el registro del módulo.\n' ;;
  web_start_failed) fmt='El servicio Web no arrancó; se liberaron los nuevos puertos públicos reservados.\n' ;;
  proxy_protocols_head) fmt='  ¿Qué protocolos? Responde a cada uno por separado.\n' ;;
  ask_proxy_vmess) fmt='    vmess [Y/n] ' ;;
  ask_proxy_vless) fmt='    vless [Y/n] ' ;;
  ask_proxy_trojan) fmt='    trojan [Y/n] ' ;;
  ask_proxy_shadowsocks) fmt='    shadowsocks [Y/n] ' ;;
  proxy_none_selected) fmt='  No se seleccionó ningún protocolo; se omite por completo el módulo proxy.\n' ;;
  modules_are) fmt='Módulos: %s\n' ;;
  port_busy) fmt='El puerto %s ya está ocupado por otro proceso.\nLibéralo o elige otros puertos con VPSSRV_PUBLIC_HTTP_PORT / VPSSRV_PUBLIC_HTTPS_PORT,\no configura VPSSRV_PUBLIC_ENABLE=0 para omitir la página pública. Compruébalo con:\n  ss -lntp "( sport = :%s )"\n' ;;
  iperf_installing) fmt='Instalando iperf3 desde la distribución ...\n' ;;
  iperf_failed) fmt='No se pudo instalar iperf3 (consulta la salida de apt anterior). La instalación se detuvo; corrige el repositorio y vuelve a ejecutar el script.\n' ;;
  anytls_arch) fmt='El módulo anytls requiere x86-64; este host es %s. Se omite porque el binario sing-box incluido no podría ejecutarse aquí.\n' ;;
  proxy_arch) fmt='El módulo proxy requiere x86-64; este host es %s. Se omite porque el binario sing-box incluido no podría ejecutarse aquí.\n' ;;
  iperf_web_required) fmt='El módulo iperf3 no funciona sin el módulo web: solo la consola puede abrir o cerrar su ventana. Añade "web" a VPSSRV_MODULES o elimina "iperf3".\n' ;;
  anytls_start) fmt='\nInstalando el módulo anytls ...\n' ;;
  proxy_start) fmt='\nInstalando el módulo proxy (%s) ...\n' ;;
  line_modules) fmt='  módulos:   %s\n' ;;
  line_public) fmt='  pública:   http://%s:%s/ y https://%s:%s/ (sin iniciar sesión)\n' ;;
  line_also) fmt='  también en: %s\n' ;;
  line_public_off) fmt='  pública:   desactivada (VPSSRV_PUBLIC_ENABLE=0)\n' ;;
  line_iperf) fmt='  iperf3:    listo, ventana cerrada; abre una desde la consola (puerto %s)\n' ;;
  line_iperf_off) fmt='  iperf3:    no instalado\n' ;;
  found_install) fmt='\nSe encontró una instalación existente: vps-server %s, módulos %s.\n' ;;
  ask_upgrade) fmt='¿Conservar su configuración y actualizar a %s? [Y/n] ' ;;
  reconfigure) fmt='Reconfigurando desde cero. La contraseña de la consola, el puerto, los certificados y el registro de visitantes se conservan en cualquier caso.\n' ;;
  upgrade_keeping) fmt='Se conservan %s ajustes registrados.\n' ;;
  upgrade_anytls_kept) fmt='Se conserva el nodo anytls existente en el puerto %s; su contraseña no cambia y los clientes configurados siguen funcionando.\n' ;;
  upgrade_proxy_kept) fmt='Se conservan los nodos proxy existentes (%s); sus puertos y credenciales no cambian y los clientes configurados siguen funcionando.\n' ;;
  upgrade_no_new) fmt='Esta versión no añade ajustes nuevos.\n' ;;
  upgrade_new_head) fmt='\nEsta versión añade ajustes que la instalada no tenía. Pulsa Intro para aceptar el valor predeterminado:\n' ;;
  upgrade_new_item) fmt='  %s = %s (se aplicó el valor predeterminado)\n' ;;
  ask_new_var) fmt='  %s [%s]: ' ;;
  upgrade_vars_unknown) fmt='La versión instalada no registró qué ajustes admitía, por lo que no se puede saber cuáles son nuevos. Se conserva todo lo que registró; lo demás usa el valor predeterminado documentado en .env.example. Vuelve a ejecutar y responde "n" arriba para revisar todos los ajustes.\n' ;;
  language_menu) fmt='Idioma:\n  1) English\n  2) 简体中文\n  3) Español\n' ;;
  language_choice) fmt='Choice / 选择 / Elección [%s]: ' ;;
  language_invalid) fmt='Elija 1, 2 o 3.\n' ;;
  host_placeholder) fmt='<este-servidor>' ;;
  error_prefix) fmt='error: ' ;;
  public_requires_openssl) fmt='La configuración pública requiere openssl\n' ;;
  lucky_public_warning) fmt='ADVERTENCIA: la administración pública de Lucky envía credenciales por HTTP sin cifrar.\n' ;;
  lucky_public_confirm_prompt) fmt='Escribe I ACCEPT PUBLIC HTTP en la terminal del servidor para continuar: ' ;;
  lucky_public_confirm_required) fmt='Se requiere confirmación para habilitar la administración pública de Lucky\n' ;;
  ask_lucky_port) fmt='  Puerto de administración de Lucky [16601]: ' ;;
  ask_lucky_public) fmt='  ¿Exponer públicamente la administración de Lucky por HTTP sin cifrar? [y/N] ' ;;
  lucky_http_warning) fmt='ADVERTENCIA: las credenciales de administración de Lucky viajan sin cifrar por HTTP. Prefiere el acceso privado o un proxy TLS.\n' ;;
  lucky_http_confirm_prompt) fmt='Escribe I ACCEPT PUBLIC HTTP para confirmar: ' ;;
  lucky_explicit_confirm) fmt='La administración pública de Lucky requiere confirmación explícita\n' ;;
  frps_arch) fmt='frps requiere linux amd64\n' ;;
  lucky_arch) fmt='Lucky requiere linux amd64\n' ;;
  frps_port_verify) fmt='No se pudo verificar el puerto frps existente; se rechazó la instalación web\n' ;;
  frps_console_conflict) fmt='El puerto de consola %s entra en conflicto con el bindPort de frps existente\n' ;;
  node_meter_failed) fmt='No se pudo iniciar el servicio de tráfico o límites de nodos; los servicios proxy permanecen detenidos. Comprueba: journalctl -u vps-server-node-meter.service -e\n' ;;
  proxy_migration_failed) fmt='No se pudo integrar el servicio AnyTLS anterior en el proxy unificado; la instalación se detuvo. Conserva la copia de migración y comprueba el estado del servicio original.\n' ;;
  frps_install_failed) fmt='Falló la instalación de frps\n' ;;
  lucky_install_failed) fmt='Falló la instalación de Lucky\n' ;;
  lucky_port_verify) fmt='No se pudo verificar el puerto de administración de Lucky existente; se rechazó la instalación web\n' ;;
  lucky_console_conflict) fmt='El puerto de consola %s entra en conflicto con el puerto de administración de Lucky existente\n' ;;
  *) fmt="$key\n" ;;
esac
